content.text:
131:.rp-report {
=== rv section bounds ===
  font-size: 0.6875rem;
  letter-spacing: 0.08em;
  color: var(--rp-text-faint);
  margin-top: var(--rp-s5);
  max-width: 84ch;
  line-height: 1.7;
}

/* Screen reader only text (used by charts and the loading status). */
.rp-sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
